const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=3)=>v==null?'—':Number(v).toFixed(d),table=(heads,rows)=>'<table><thead><tr>'+heads.map(v=>'<th>'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
let A,E,paired=[],U='domestic';const query=new URLSearchParams(location.search);
const kst=s=>s?new Date(s).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false}):'—';
const mktLabel=code=>U==='global'?({'1306.T':'TOPIX','^GSPC':'S&P500'}[A.markets?.[code]]||'시장'):'KOSPI';
const sourceLinks=ids=>'<div class="sources">'+ids.map(id=>{const s=E.sources[id];return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} · ${esc(s.date)} ↗</a><span>${esc(s.scope)}</span>`:'';}).join('')+'</div>';
const sumOf=(i,c,y)=>A.summary.find(s=>s.indicator===i&&s.stock===c&&s.years===y);
function matrix(){const years=+$('years').value;const codes=Object.keys(A.stocks);const onlyMapped=$('only-mapped').checked;
 const inds=Object.values(A.indicators).filter(i=>!onlyMapped||i.mappedStocks?.some(c=>codes.includes(c)));
 $('matrix').innerHTML=table(['지표',...codes.map(c=>A.stocks[c])],inds.map(i=>[esc(i.name),...codes.map(c=>{const s=sumOf(i.id,c,years),r=years===1?s?.contemporaneous?.r:s?.contemporaneous?.partialR;const robust=s?.status==='재검토할 연관성',mapped=s?.mapped;if(onlyMapped&&!mapped)return '<span class="dim">·</span>';
  return `<button data-i="${i.id}" data-s="${c}" class="${robust?'hl':''}${mapped?' mapped':''}" title="${esc((mapped?'전달경로 지정 · ':'')+(s?.status||''))}${robust&&s.best?` · 최대 시차 ${s.best.lag}개월 부분상관 ${fmt(s.best.partialR,2)}`:''}" style="background:rgba(37,99,235,${r==null?0:.07+Math.abs(r)*.55})">${fmt(r,2)}</button>`;})]));
 $('matrix').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('indicator').value=b.dataset.i;$('stock').value=b.dataset.s;pair();$('pair').scrollIntoView({behavior:'smooth'});});}
// 하이라이트: 갱신 상태 · 직전 대비 변경 · 검토할 연관성(전달경로 지정 쌍 우선)
function highlights(){const years=+$('years').value,ageH=(Date.now()-Date.parse(A.generatedAt))/36e5,ch=A.changes||{};
 const status=`<div class="hl-status ${ageH>30?'warn':'ok'}"><b>${ageH>30?'갱신 지연':'오늘 갱신'}</b> 분석 생성 ${esc(kst(A.generatedAt))} · 기준 월 ${esc(A.asOfMonth)}(완료 월) · 주가는 매 평일 아침 수집 후 재계산${ch.previousGeneratedAt?` · 직전 계산 ${esc(kst(ch.previousGeneratedAt))}`:''}</div>`;
 const pairBtn=(x,extra='')=>`<button class="chip" data-i="${x.indicator}" data-s="${x.stock}" data-y="${x.years}">${esc(A.indicators[x.indicator]?.name||x.indicator)} × ${esc(A.stocks[x.stock]||x.stock)} <small>${x.years}년${extra}</small></button>`;
 const diff=(ch.added?.length||ch.removed?.length)?`<div class="hl-box"><h3>직전 계산 대비 변화</h3>${ch.added?.length?`<p><span class="tag up">신규</span> ${ch.added.map(x=>pairBtn(x)).join('')}</p>`:''}${ch.removed?.length?`<p><span class="tag down">해제</span> ${ch.removed.map(x=>pairBtn(x)).join('')}</p>`:''}</div>`:`<div class="hl-box"><h3>직전 계산 대비 변화</h3><p class="muted">‘재검토할 연관성’ 판정이 바뀐 조합 없음</p></div>`;
 const robust=A.summary.filter(s=>s.years===years&&s.status==='재검토할 연관성'&&s.best).sort((a,b)=>(b.mapped-a.mapped)||Math.abs(b.best.partialR)-Math.abs(a.best.partialR));
 const mapped=robust.filter(s=>s.mapped),other=robust.length-mapped.length;
 const list=`<div class="hl-box"><h3>${years}년 · 검토할 연관성 <small>q&lt;0.05 · 48개월+ · 전후반·가격수익률 부호 일치</small></h3>${mapped.length?`<p>${mapped.slice(0,14).map(s=>pairBtn(s,` · ${s.best.lag>0?'+':''}${s.best.lag}M · ${fmt(s.best.partialR,2)}`)).join('')}</p>`:'<p class="muted">전달경로가 지정된 조합 중 기준 통과 없음</p>'}${other?`<p class="muted">전달경로 미지정 조합 ${other}개는 통계 탐색 결과라 하이라이트에서 제외(행렬에서 테두리로 표시).</p>`:''}</div>`;
 $('highlights').innerHTML=status+'<div class="hl-grid">'+diff+list+'</div>';
 $('highlights').querySelectorAll('.chip').forEach(b=>b.onclick=()=>{$('years').value=b.dataset.y;$('indicator').value=b.dataset.i;$('stock').value=b.dataset.s;matrix();pair();$('pair').scrollIntoView({behavior:'smooth'});});}
function pair(){const iid=$('indicator').value,code=$('stock').value,years=+$('years').value,info=A.indicators[iid],e=E.byPair?.[iid+':'+code];if(!info||!A.stocks[code])return;history.replaceState(null,'',`${location.pathname}?indicator=${iid}&stock=${encodeURIComponent(code)}`);$('pair-title').textContent=info.name+' × '+A.stocks[code];
 const fx=e?null:payloadEffect(iid,code);
 $('evidence').innerHTML=e?`<span class="badge">${esc(e.status)} · 자료 ${e.sourceIds.length}개</span>${e.direction?`<p><b>지표 상승: ${esc(e.direction.up)} / 하락: ${esc(e.direction.down)}</b> · 조건부 실적 영향</p>`:""}<p>${esc(e.text)}</p><p><b>실적 반영 시점:</b> ${esc(e.lag)}</p>${e.notes.map(n=>'<p class="muted">'+esc(n)+'</p>').join('')}${sourceLinks(e.sourceIds)}`:fx?`<span class="badge">전달경로 지정(카탈로그) · 정량 근거 미검증</span><p>${esc(fx.text)}</p><p><b>실적 반영 시점:</b> ${esc(fx.lag)}</p>`:'<p>이 조합은 사업상 전달경로가 지정되지 않았습니다. 아래 수치는 전체 조합에 대한 통계 탐색이며 직접적인 실적 영향을 뜻하지 않습니다.</p>';
 const periods=A.summary.filter(s=>s.indicator===iid&&s.stock===code);$('periods').innerHTML=table(['기간','동월 n','동월 r / 부분상관','탐색 최대 시차','부분상관','β [95% 구간]','q','전후반 부호','판정'],periods.map(s=>{const b=s.best,z=s.contemporaneous;return[s.years+'년',z?.n??0,fmt(z?.r)+' / '+fmt(z?.partialR),b?b.lag+'개월':'—',fmt(b?.partialR),b?`${fmt(b.beta)} [${fmt(b.ciLow)}, ${fmt(b.ciHigh)}]`:'—',fmt(b?.q,4),b?(b.sameSignHalves?'일치':'미확인/불일치'):'—',s.status==='재검토할 연관성'?`<b class="hl-text">${esc(s.status)}</b>`:esc(s.status)];}));
 const rs=A.results.filter(r=>r.indicator===iid&&r.stock===code&&r.years===years);$('lag-chart').innerHTML=rs.length?`<svg viewBox="0 0 850 200" role="img" aria-label="시차별 상관계수"><line x1="20" x2="830" y1="92" y2="92" stroke="#bccbde"/>${rs.map((r,j)=>{const v=years===1?r.r:r.partialR,x=25+j*42;return `<rect x="${x}" y="${v>0?92-v*80:92}" width="29" height="${Math.abs(v||0)*80}" fill="${r.q!=null&&r.q<.05?'#d97706':'#2563eb'}"><title>${r.lag}개월: ${fmt(v)}, n=${r.n}${r.q!=null?', q='+fmt(r.q,4):''}</title></rect><text x="${x+14}" y="185" text-anchor="middle">${r.lag}</text>`;}).join('')}<text x="20" y="15">${years===1?'단순 상관 (소표본 참고)':'시장('+mktLabel(code)+') 통제 부분상관'} · 주황 = q&lt;0.05</text></svg>`:'<p class="empty">'+esc(info.reason||'유효 표본 부족')+'</p>';
 $('lags').innerHTML=table(['시차(월)','n','Pearson r','Spearman','부분상관','β','95% 하한','95% 상한','p','다중검정 q'],rs.map(r=>[r.lag,r.n,fmt(r.r),fmt(r.spearman),fmt(r.partialR),fmt(r.beta),fmt(r.ciLow),fmt(r.ciHigh),fmt(r.p,4),fmt(r.q,4)]));pairedTable();}
let FX={};const payloadEffect=(iid,code)=>FX[iid]?.[code]||null;
function pairedTable(){const iid=$('indicator').value,code=$('stock').value,L=+$('lag').value,N=+$('years').value*12,P=A.panel,start=P.months.length-N;const M=P.marketByStock?P.marketByStock[code]:P.market;paired=[];for(let y=start;y<P.months.length;y++){const x=y-L;if(x<start||x>=P.months.length)continue;const v=P.macro[iid]?.[x],r=P.stock[code]?.[y],m=M?.[y];if(v==null||r==null||m==null)continue;paired.push([P.months[x],P.months[y],v,r,m]);}$('transform').textContent=(A.indicators[iid].transform||A.indicators[iid].reason)+' · 지표 변환값과 월수익률의 실제 대응표 · '+paired.length+'행';$('paired').innerHTML=table(['지표 기준월','주가 수익률 월','지표 변화값','수정종가 수익률 (%)',mktLabel(code)+' (%)'],paired.map(r=>r.map((v,i)=>i<2?v:fmt(v,4))));}
async function load(u){U=u;document.querySelectorAll('#universe button').forEach(b=>b.classList.toggle('active',b.dataset.u===U));$('coverage').textContent='계산 결과 불러오는 중…';
 const res=await fetch(U==='global'?'/api/analysis-global':'/api/analysis');if(!res.ok)throw Error('분석 파일을 읽을 수 없습니다');({analysis:A,evidence:E,effects:FX={}}=await res.json());if(!A?.summary)throw Error(U==='global'?'해외 분석 결과가 아직 없습니다':'분석 결과 없음');
 $('coverage').textContent=`${U==='global'?'일본·미국 비교 종목':'국내 커버리지'} · ${A.asOfMonth} 완료 월 기준 · ${A.indicatorCount}개 지표 × ${A.stockCount}개 종목 · 4개 기간 · ${A.estimableIndicators}개 지표 시차 계산 · ${A.hypothesisCount.toLocaleString()}개 회귀 다중검정 · 시장 통제 ${U==='global'?'TOPIX(ETF)·S&P500':'KOSPI'}`;
 $('indicator').innerHTML=Object.values(A.indicators).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('');$('stock').innerHTML=Object.entries(A.stocks).map(([c,n])=>`<option value="${esc(c)}">${esc(n)}</option>`).join('');$('lag').innerHTML=A.method.lags.map(l=>`<option value="${l}" ${l===0?'selected':''}>${l}개월</option>`).join('');
 if(A.indicators[query.get('indicator')])$('indicator').value=query.get('indicator');if(A.stocks[query.get('stock')])$('stock').value=query.get('stock');
 $('cases').innerHTML=U==='global'?'<p class="muted">해외 종목은 실적·공시 대입 사례 미작성(국내 커버리지만 제공).</p>':E.cases.map(c=>`<article class="case"><h3>${esc(c.title)}</h3><span class="badge">${esc(c.type)}</span>${table(c.columns,c.rows.map(r=>r.map(esc)))}<p>${esc(c.conclusion)}</p>${sourceLinks(c.sourceIds)}</article>`).join('');
 $('method').innerHTML=`<p>${esc(A.method.model)}${U==='global'?' (해외: KOSPI 대신 각 시장지수)':''}</p><p>${esc(A.method.returns)}</p><ul>${A.method.limits.map(l=>'<li>'+esc(l)+'</li>').join('')}</ul><p>${esc(E.policy)}</p><p class="sources">주가 원천: ${esc(A.priceSource)} · <a href="https://help.yahoo.com/kb/SLN28256.html" target="_blank" rel="noopener">수정종가 정의 ↗</a>${U==='global'?'':' · 월말 종가 대조: Naver Finance'} · 분석 생성 ${esc(kst(A.generatedAt))}</p>`;
 $('quality').innerHTML=Object.entries(A.quality).map(([c,q])=>`<p><b>${esc(A.stocks[c])}</b> ${q.checkedMonths}개월 대조 / ${q.within1pct}개월 차이 1% 미만 · 제외 월: ${esc(q.excludedMonths.join(', ')||'없음')} · <a href="${esc(A.stockSources[c])}" target="_blank" rel="noopener">주가 원천</a></p>`).join('');
 $('channels').innerHTML=A.channels.length?table(['설명지표','운영지표','시차','n','상관'],A.channels.map(c=>[esc(A.indicators[c.indicator].name),esc(A.indicators[c.target].name),c.lag,c.n,fmt(c.r)])):'<p class="muted">해외는 운영지표 탐색 없음</p>';
 highlights();matrix();pair();}
$('years').onchange=()=>{highlights();matrix();pair();};$('only-mapped').onchange=matrix;$('indicator').onchange=pair;$('stock').onchange=pair;$('lag').onchange=pairedTable;
$('paired-download').onclick=()=>{const blob=new Blob(['﻿지표월,수익률월,지표변화값,수정종가수익률_pct,'+mktLabel($('stock').value)+'_pct\n'+paired.map(r=>r.join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`paired-${$('indicator').value}-${$('stock').value}-${$('years').value}y-lag${$('lag').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
